        Lines 66 to 70
      in
      e782dc0







           inline Stream getCurrentStream(DeviceIndex device_index) { 




             StreamHandle stream = nullptr; 




             TORCH_ERROR_CODE_CHECK(aoti_torch_get_current_stream(device_index, &stream)); 




             return Stream(stream); 




           } 








      pytorch/torch/csrc/inductor/aoti_torch/shim_common.cpp


        Lines 1510 to 1518
      in
      e782dc0







           AOTITorchError aoti_torch_get_current_stream( 




               int32_t device_index, 




               StreamHandle* ret_stream) { 




             AOTI_TORCH_CONVERT_EXCEPTION_TO_ERROR_CODE({ 




               c10::Stream stream = at::accelerator::getCurrentStream(device_index); 




               c10::Stream* stream_ptr = new c10::Stream(stream); 




               *ret_stream = reinterpret_cast<StreamHandle>(stream_ptr); 




             }); 




           } 





I'm looking for a unified way to access the underlying pointer (e.g. so a user can pass it to a raw CUDA/HIP/XPU API but it seems like there is no unified method to access this. The only method that seems close is id() which returns a StreamId which is not directly interpretable by the user (for example on CUDA some part of it might be an index into the internal pool of streams used by pytorch).
