import torch
import torch.nn.functional as F


def test_one_hot_bounds(device):
    print(f"\n--- Testing on {device} ---")
    try:
        num_classes = 8
        invalid_indices = torch.tensor([8], dtype=torch.long).to(device)
        # invalid_indices = torch.tensor([-1], dtype=torch.long).to(device)

        result = F.one_hot(invalid_indices, num_classes=num_classes)

        result.to("cpu")
        print(f"[{device}] ✅ No Exception (Silent Failure/Inconsistency)")
        print(f"Output tensor: {result}")

    except RuntimeError as e:
        print(f"[{device}] ❌ Caught Expected Error:")
        print(f"Error Message: {e}")


test_one_hot_bounds("cpu")

if torch.backends.mps.is_available():
    test_one_hot_bounds("mps")

if torch.cuda.is_available():
    test_one_hot_bounds("cuda")
